import {meta} from './schema.js';
import {mountLeaseBuilder} from './lease-builder.js';
import {escapeHTML as esc,dropdown,updateDropdown} from './controls.js';
import {resultsTable,bindResultsTables} from './results-table.js';
import {searchControl,matchesSearch,onSearch,bindSearch} from './search.js';
import {normaliseMultiValues} from './field-values.js';
bindResultsTables(document);
bindSearch(document);
const app=document.querySelector('#app');
let state={};
const icons={home:'M3 10 12 3l9 7v11h-7v-7h-4v7H3Z',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',file:'M14 2H4v20h16V8ZM14 2v6h6M8 13h8M8 17h8',wallet:'M3 5h16v4H3ZM3 9v12h18V9M16 13h5v5h-5Z',tool:'m14 7 3-3 3 1 1 3-3 3-4-1-9 10-3-3 10-9V4l3-2',chart:'M4 20V10M10 20V4M16 20v-8M22 20H1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',check:'m5 12 4 4L19 6',calendar:'M3 5h18v17H3ZM7 2v6M17 2v6M3 11h18',up:'M12 20V4m-6 6 6-6 6 6',down:'M12 4v16m-6-6 6 6 6-6',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',menu:'M3 6h18M3 12h18M3 18h18',folder:'M3 6h7l2 3h9v12H3Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[n]||icons.file}"/></svg>`;

const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const nav=[['Overview','overview','grid'],['Properties','properties','home'],['Tenants','tenants','people'],['Leases','leases','file'],['Rent & payments','payments','wallet'],['Expenses','expenses','down'],['Maintenance','work','tool'],['Documents','documents','folder'],['Reports','reports','chart'],['More','more','menu'],['Settings','settings','settings']];
function shell(content,title='Overview'){return `<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><img src="/favicon.svg" alt="">hearth</a><div class="nav-label">YOUR WORKSPACE</div>${nav.map(([label,key,ic],i)=>`${i===4?'<div class="nav-label">MONEY & OPERATIONS</div>':''}<a class="nav-link ${location.hash.slice(1).split('/')[0]===key||(!location.hash&&key==='overview')?'active':''}" href="#${key}">${icon(ic)}${label}</a>`).join('')}<div class="sidebar-foot"><span class="dot"></span>Local workspace · Saved on this computer</div></aside><main class="main"><header class="topbar"><button class="icon mobile-toggle" aria-label="Open navigation">${icon('menu')}</button><span class="crumb">Workspace &nbsp; / &nbsp; <strong>${esc(title)}</strong></span><div class="top-right"><span class="date">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span><span class="mini"><span class="dot"></span>Local</span><span class="avatar">${esc((state.owner?.name||'You').split(' ').map(s=>s[0]).slice(0,2).join(''))}</span></div></header><div class="workspace">${state.demo?`<div class="demo-banner"><span><strong>Interactive preview</strong> · Fictional sample records. Try adding, editing, and uploading.</span><a href="http://127.0.0.1:8768/" target="_blank">Open your empty workspace ↗</a></div>`:""}${content}</div></main></div>`}
const modal=document.querySelector('#modal');
let filters={},tabMode={},toastTimer;
const today=()=>state.today||new Date().toLocaleDateString('en-CA');
const records=k=>state[k]||[];
const find=(k,id)=>records(k).find(r=>r.id===id);
const label=(k,id)=>{const r=find(k,id);return r?.name||r?.title||r?.description||'—'};
const total=(rows,key='amount')=>rows.reduce((s,r)=>s+Math.round(Number(r[key]||0)*100),0)/100;
const dateText=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const displayName=r=>r.name||r.title||r.description||meta[r.kind]?.one||'Record';
const chargePaid=c=>total(records('payments').filter(p=>p.charge_id===c.id&&!p.void));
const balance=c=>Math.max(0,Math.round((Number(c.amount)-chargePaid(c))*100)/100);
const chargeStatus=c=>c.void?'Void':balance(c)===0?'Paid':c.date<today()?'Overdue':chargePaid(c)>0?'Partial':'Open';
const workCosts=w=>records('expenses').filter(e=>e.work_id===w.id&&!e.void);
const badge=(s)=>`<span class="badge ${['Overdue','Urgent','Void','Declined'].includes(s)?'bad':['Unpaid','Open','Partial','Scheduled','On hold','High','Draft'].includes(s)?'warn':['Ended','Former','Cancelled','Inactive'].includes(s)?'neutral':''}">${esc(s||'—')}</span>`;
const buttonTypes={
 create:new Set(['add','create-receipt','pay','work-expense']),
 danger:new Set(['delete','email-disconnect','remove','void'])
};
const buttonType=(action,type='')=>buttonTypes.create.has(action)?'create':buttonTypes.danger.has(action)?'danger':type||'neutral';
const buttonClass=(action,type='')=>`button-${buttonType(action,type)}`;
const btn=(text,action,kind='',id='',type='')=>`<button class="${buttonClass(action,type)}" data-action="${action}" data-kind="${kind}" data-id="${id}">${esc(text)}</button>`;
const link=(kind,id,text)=>`<a class="row-title" href="#${kind}/${id}">${esc(text||label(kind,id))}</a>`;
function toast(msg){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
async function copyText(value){try{await navigator.clipboard.writeText(value)}catch{const input=document.createElement('textarea');input.value=value;input.setAttribute('readonly','');input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();if(!document.execCommand('copy'))throw Error('Copy was blocked by the browser.');input.remove()}}
async function api(path,data){const r=await fetch('/api/'+path,data?{method:'POST',headers:{'Content-Type':'application/json','X-Hearth-Token':state.token},body:JSON.stringify(data)}:{});const result=await r.json();if(!r.ok)throw Error(result.error||'Something went wrong.');return result}
async function refresh(){state=await api('state');render()}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>${title==='Settings'?emailSettingsPanel():''}`}
function panel(title,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>${body}</section>`}
function googleEmailInstructions(){const gmailScope='https://www.googleapis.com/auth/gmail.send',sender=state.owner?.email||'your Google Workspace email',domain=sender.includes('@')?sender.split('@').pop():'your organization';return `<details class="setup-guide" open><summary>Full Google Workspace setup instructions</summary><div class="setup-guide-body"><ol class="setup-steps"><li><strong>Choose or create a Google Cloud project.</strong><br><a href="https://console.cloud.google.com/projectselector2/home/dashboard" target="_blank" rel="noopener">Open the Google Cloud project selector ↗</a>. Sign in with an administrator account for ${esc(domain)}. Choose an existing internal project or create one named <em>Hearth</em>.</li><li><strong>Enable the Gmail API.</strong><br><a href="https://console.cloud.google.com/apis/library/gmail.googleapis.com" target="_blank" rel="noopener">Open the Gmail API page ↗</a>, confirm the correct project at the top, and select <strong>Enable</strong>.</li><li><strong>Configure the Google Auth Platform.</strong><br><a href="https://console.cloud.google.com/auth/branding" target="_blank" rel="noopener">Open Branding ↗</a>. If prompted, select <strong>Get started</strong>. Use <em>Hearth</em> as the app name, choose ${esc(sender)} as the support email, enter the same contact email, and save.</li><li><strong>Keep the app inside your Workspace.</strong><br><a href="https://console.cloud.google.com/auth/audience" target="_blank" rel="noopener">Open Audience ↗</a> and choose <strong>Internal</strong>. This limits the connection to accounts in your Google Workspace organization.</li><li><strong>Confirm the Gmail permission.</strong><br><a href="https://console.cloud.google.com/auth/scopes" target="_blank" rel="noopener">Open Data Access ↗</a>. Add this exact Gmail API scope if Google asks you to declare scopes:<div class="copy-value"><code>${gmailScope}</code><button type="button" data-action="copy-text" data-copy="${gmailScope}">Copy scope</button></div>Hearth also requests the basic <code>openid</code> and <code>email</code> identity scopes so it can verify the sender account.</li><li><strong>Create the OAuth client.</strong><br><a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener">Open Clients ↗</a>, select <strong>Create client</strong>, choose <strong>Desktop app</strong>, name it <em>Hearth local app</em>, and select <strong>Create</strong>.</li><li><strong>Download the JSON file.</strong><br>Use the download button beside the new client. Keep this file private. Select that file in the Hearth form below and choose <strong>Save Google connection file</strong>.</li><li><strong>Connect the mailbox.</strong><br>After the file is saved, select <strong>Connect ${esc(sender)}</strong>. Sign in to the intended mailbox and approve the request to send email.</li><li><strong>If Google says the app is blocked.</strong><br>A Workspace administrator should open <a href="https://admin.google.com/ac/owl" target="_blank" rel="noopener">Admin console → API controls ↗</a>, review the OAuth client, and allow it for Gmail. See Google’s <a href="https://support.google.com/a/answer/7281227" target="_blank" rel="noopener">official app-access instructions ↗</a>.</li></ol><div class="note"><strong>What Hearth stores:</strong> It never receives your Google password. Windows encrypts the OAuth client and refresh token for your Windows account. These credentials are kept outside Hearth backups. You can disconnect and remove them at any time.</div><p class="muted small">Official references: <a href="https://developers.google.com/workspace/gmail/api/quickstart/python" target="_blank" rel="noopener">Gmail API OAuth setup ↗</a> · <a href="https://developers.google.com/workspace/gmail/api/guides/sending" target="_blank" rel="noopener">Gmail sending guide ↗</a></p></div></details>`}
function emailSettingsPanel(){const service=state.email_service||{},email=service.email||state.owner?.email||'';let body;if(service.connected){body=`<div class="panel-body"><div class="email-connection"><div><span class="badge">Connected</span><h3>${esc(email)}</h3><p class="muted small">Hearth can send locked payment receipts through this Google Workspace mailbox.</p></div>${btn('Disconnect','email-disconnect','','')}</div>${googleEmailInstructions()}</div>`}else if(service.configured){body=`<div class="panel-body"><p>The Google OAuth client is ready. Connect the Workspace mailbox to enable receipt email.</p><div class="actions">${btn('Connect '+email,'email-connect','','','primary')}${btn('Replace OAuth file','email-replace')}</div><p class="muted small">Google will open in a separate window. Sign in as ${esc(email)} and approve permission to send mail.</p>${googleEmailInstructions()}</div>`}else{body=`<div class="panel-body"><p>Send receipts from your Google Workspace mailbox without storing your Google password.</p>${googleEmailInstructions()}<form id="email-setup-form" class="email-setup-form"><h3>Add the downloaded OAuth client file</h3><div class="form-grid"><label class="field">Sender email<input name="email" type="email" value="${esc(email)}" placeholder="name@company.com" required></label><label class="field">Google OAuth client JSON<input name="credentials" type="file" accept="application/json,.json" required></label></div><div class="actions email-setup-actions"><button class="button-primary" type="submit">Save Google connection file</button></div><p class="form-error" role="alert"></p></form></div>`}return panel('Google Workspace email',body,'','Send receipts and future tenant messages from Hearth.')}
function collapsiblePanel(title,body,action='',sub='',open=false){return `<details class="panel collapsible-panel"${open?' open':''}><summary class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><span class="collapse-indicator" aria-hidden="true"></span></summary>${action?`<div class="panel-section-action">${action}</div>`:''}${body}</details>`}
let kpiDetails=[],tableScope='',tableCounts=new Map();
const drill=(kind,rows,note='')=>({sections:[{kind,rows}],note});
function statTiles(items){return `<section class="stats">${items.map(([title,value,sub,ic,details])=>{if(!details)throw Error('Missing KPI details: '+title);const key=kpiDetails.push({title,value,sub,...details})-1;return `<button type="button" class="stat" data-action="kpi" data-id="${key}" aria-label="View ${esc(title)}: ${esc(value)}"><span class="label">${esc(title)}${icon(ic)}</span><span class="value">${esc(value)}</span><span class="meta">${esc(sub)}</span><span class="stat-hint">View details →</span></button>`}).join('')}</section>`}
function kpiDialog(key){const detail=kpiDetails[Number(key)];if(!detail)return;tableScope='kpi-'+key;tableCounts.clear();const body=detail.sections.map(({kind,rows,title})=>`<section class="kpi-section"><h3>${esc(title||meta[kind]?.name||'Files')} · ${rows.length}</h3>${rows.length?rowsTable(kind,rows):empty('No matching records','There are no records contributing to this total.')}</section>`).join('');openModal(detail.title,`<div class="modal-body"><div class="kpi-summary"><strong>${esc(detail.value)}</strong><p>${esc(detail.sub)}</p></div>${detail.note?`<p class="note">${esc(detail.note)}</p>`:''}${body}</div><div class="modal-footer"><button data-action="close">Close</button></div>`);modal.classList.add('results-dialog');tableScope='';}

function empty(title,copy,kind=''){return `<div class="empty"><div class="empty-icon">${icon(meta[kind]?.icon||'folder')}</div><h3>${esc(title)}</h3><p>${esc(copy)}</p>${kind?btn('Add '+meta[kind].one,'add',kind):''}</div>`}
function table(headers,rows){const signature=JSON.stringify(headers),count=tableCounts.get(signature)||0;tableCounts.set(signature,count+1);return resultsTable(headers,rows,`${location.hash}|${tableScope}|${signature}|${count}`,{searchable:!!tableScope||location.hash.includes('/')||!meta[location.hash.slice(1)]})}
function bars(items){const max=Math.max(1,...items.map(r=>r.amount));return items.length?items.map(r=>`<div class="bar-row"><div class="bar-label"><span>${esc(r.name)}</span><strong>${cash(r.amount)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,r.amount/max*100)}%"></div></div></div>`).join(''):'<p class="muted small">Category totals appear when you record expenses.</p>'}
function categoriesOf(rows){const map={};rows.forEach(r=>map[r.category]=(map[r.category]||0)+Math.round(Number(r.amount)*100));return Object.entries(map).map(([name,c])=>({name,amount:c/100})).sort((a,b)=>b.amount-a.amount)}
function propertyCard(p){const ls=records('leases').filter(l=>l.property_id===p.id&&l.status==='Active');return `<article class="property-card"><a href="#properties/${p.id}" class="property-art" aria-label="Open ${esc(p.name)}">${p.photo_id?`<img class="home-photo" src="/api/files/${p.photo_id}" alt="${esc(p.name)}">`:`<svg viewBox="0 0 140 110" fill="none"><path d="M15 49 70 10l55 39M25 43v59h90V43M59 102V69h23v33M36 57h14v19H36ZM91 57h14v19H91ZM64 40h13v15H64ZM14 102h112M96 25V12h12v23"/></svg>`}${badge(ls.length?'Occupied':'Vacant')}</a><div class="card-body"><div class="photo-action">${btn(p.photo_id?'Change photo':'Add photo','property-photo','properties',p.id)}</div><h3><a href="#properties/${p.id}">${esc(p.name)}</a></h3><p>${esc(p.address)}${p.city?', '+esc(p.city):''}</p><div class="card-facts"><span><small>${ls.length?'Monthly rent':'Market rent'}</small><strong>${cash(ls.length?total(ls,'rent'):p.market_rent)}</strong></span><span><small>Open work</small><strong>${records('work').filter(w=>w.property_id===p.id&&!['Completed','Cancelled'].includes(w.status)).length} requests</strong></span><span><small>Type</small>${esc(p.type||'House')}</span></div></div></article>`}
function overview(){const month=today().slice(0,7);const paid=records('payments').filter(p=>!p.void&&p.date?.startsWith(month)&&p.category!=='Security deposit');const spent=records('expenses').filter(e=>!e.void&&e.status==='Paid'&&e.paid_date?.startsWith(month));const open=records('work').filter(w=>!['Completed','Cancelled'].includes(w.status));const due=records('charges').filter(c=>!c.void&&balance(c)>0&&c.date<=today());const expiring=records('leases').filter(l=>l.status==='Active'&&l.end&&l.end>=today()&&l.end<=new Date(Date.now()+30*864e5).toISOString().slice(0,10));return pageHead('A clear view of home.','Your properties, people, and paperwork. All in one place.',btn('Record expense','add','expenses')+btn('+ Add property','add','properties','','primary'))+statTiles([['Properties',String(records('properties').length),`${records('leases').filter(l=>l.status==='Active').length} active leases`,'home',drill('properties',records('properties'))],['Rent & income collected',cash(total(paid)),'This month · excluding deposits','up',drill('payments',paid)],['Expenses paid',cash(total(spent)),'This month · cash basis','down',drill('expenses',spent)],['Open work orders',String(open.length),`${open.filter(w=>w.priority==='Urgent').length} marked urgent`,'tool',drill('work',open)]])+(!records('properties').length?`<div class="overview-welcome">${icon('home')}<div><h3>Start with your first house.</h3><p>Add a property, then its tenants and lease. Your records are saved on this computer, including uploaded receipts and documents.</p>${btn('Add a property','add','properties','','primary')}</div></div>`:'')+`<div class="grid-two"><div>${panel('Your properties',records('properties').length?`<div class="panel-body property-grid">${records('properties').slice(0,4).map(propertyCard).join('')}</div>`:empty('Your portfolio starts here','Bring your houses and their histories together.','properties'),'<a class="text-link" href="#properties">View all →</a>')}${panel('Recent activity',records('payments').length||records('expenses').length?table(['Date','Activity','Property','Amount'],[...records('payments').filter(r=>!r.void).map(r=>({...r,sign:'+'})),...records('expenses').filter(r=>!r.void).map(r=>({...r,sign:'−'}))].sort((a,b)=>b.created.localeCompare(a.created)).slice(0,6).map(r=>`<tr><td>${dateText(r.date)}</td><td>${link(r.kind,r.id,r.description||r.category)}<span class="sub">${r.kind==='payments'?'Payment received':'Expense recorded'}</span></td><td>${esc(label('properties',r.property_id))}</td><td class="num">${r.sign}${cash(r.amount)}</td></tr>`)):empty('Nothing recorded yet','Income and expenses will appear here as you add them.'))}</div><div>${panel('On your radar',`<div class="panel-body"><div class="task-row"><div class="task-icon">${icon('wallet')}</div><div class="task-copy"><b>${cash(due.reduce((s,c)=>s+balance(c),0))} due from tenants</b><span>${due.length} unpaid charges due today or earlier</span></div><a class="text-link" href="#charges">View</a></div><div class="task-row"><div class="task-icon">${icon('file')}</div><div class="task-copy"><b>${expiring.length} leases ending soon</b><span>Within the next 30 days</span></div><a class="text-link" href="#leases">View</a></div>${open.slice(0,3).map(w=>`<div class="task-row"><div class="task-icon">${icon('tool')}</div><div class="task-copy"><b>${esc(w.title)}</b><span>${esc(label('properties',w.property_id))} · ${esc(w.priority)}</span></div><a class="text-link" href="#work/${w.id}">View</a></div>`).join('')}${records('tasks').filter(t=>t.status!=='Done').slice(0,3).map(t=>`<div class="task-row"><div class="task-icon">${icon('calendar')}</div><div class="task-copy"><b>${esc(t.title)}</b><span>Due ${dateText(t.date)}</span></div><a class="text-link" href="#tasks/${t.id}">View</a></div>`).join('')}</div>`)}${panel('Where your money went',`<div class="panel-body">${bars(categoriesOf(spent).slice(0,6))}</div>`,'<a class="text-link" href="#reports">Reports →</a>','Paid expenses this month')}${panel('Keep a copy',`<div class="panel-body"><p class="muted small">A backup includes your database and every uploaded file.</p><a class="text-link" href="/api/backup">Download full backup ↓</a></div>`)}</div></div>`}
function visibleRows(kind){const f=filters[kind]||{};return records(kind).filter(r=>matchesSearch({...r,property:label('properties',r.property_id),tenant:label('tenants',r.tenant_id),coTenant:label('tenants',r.co_tenant_id)},f.q)&&(!f.property||r.property_id===f.property||kind==='properties'&&r.id===f.property)&&(!f.status||(kind==='charges'?chargeStatus(r):r.void?'Void':r.status)===f.status)&&(!f.method||r.method===f.method)&&(!f.category||r.category===f.category)&&(!f.start||(r.date||r.start||'')>=f.start)&&(!f.end||(r.date||r.start||'')<=f.end))}
function filterDropdown(kind,key,options,blank,label){return dropdown({options,value:filters[kind]?.[key]||'',blank,attrs:{'aria-label':label,'data-filter':key,'data-kind':kind}})}
function propertyFilter(kind,label='Filter by property'){return filterDropdown(kind,'property',optionsFor('ref','properties',{}),'All properties',label)}
function toolbar(kind){const f=filters[kind]||{},fields=meta[kind].fields;const status=kind==='charges'?['Open','Partial','Paid','Overdue','Void']:fields.find(x=>x[0]==='status')?.[4]||[];return `<div class="toolbar">${searchControl({scope:'page',key:kind,label:'Search '+meta[kind].name.toLowerCase(),value:f.q||''})}${fields.some(x=>x[0]==='property_id')?propertyFilter(kind):''}${status.length?filterDropdown(kind,'status',status,'All statuses','Filter by status'):''}${fields.some(x=>x[0]==='category')?filterDropdown(kind,'category',[...new Set(records(kind).map(r=>r.category).filter(Boolean))].sort(),'All categories','Filter by category'):''}${['charges','payments','expenses'].includes(kind)?`<label>From <input aria-label="From date" type="date" data-kind="${kind}" data-filter="start" value="${f.start||''}"></label><label>To <input aria-label="To date" type="date" data-kind="${kind}" data-filter="end" value="${f.end||''}"></label>`:''}${['payments','expenses'].includes(kind)?filterDropdown(kind,'method',[...new Set([...fields.find(f=>f[0]==='method')[4],...records(kind).map(r=>r.method).filter(Boolean)])],'All payment methods','Filter by payment method'):''}${Object.values(f).some(Boolean)?btn('Clear','clear',kind):''}</div>`}

function rowsTable(kind,rows){let headers, cells;
if(kind==='properties'){headers=['Property','Address','Type','Market rent','Status',''];cells=r=>[link(kind,r.id,r.name),esc([r.address,r.city].filter(Boolean).join(', ')),esc(r.type),cash(r.market_rent),badge(r.status)]}
else if(kind==='files'){headers=['File','Linked record','Size (KB)','Added',''];cells=r=>[`<button class="file-name-button" type="button" data-action="preview-file" data-id="${r.id}">${esc(r.name)}</button>`,r.record_id?link(r.kind,r.record_id,label(r.kind,r.record_id)):'General',Math.max(1,Math.round(r.size/1024)),dateText(r.created.slice(0,10))]}
else if(kind==='tenants'){headers=['Tenant','Contact','Status','Balance due',''];cells=r=>[link(kind,r.id,r.name),`${esc(r.email||'—')}<span class="sub">${esc(r.phone)}</span>`,badge(r.status),cash(records('charges').filter(c=>!c.void&&c.tenant_id===r.id).reduce((s,c)=>s+balance(c),0))]}
else if(kind==='leases'){headers=['Lease / tenant','Property','Term','Monthly rent','Status',''];cells=r=>[`${link(kind,r.id,r.name)}<span class="sub">${esc(label('tenants',r.tenant_id))}${r.co_tenant_id?' + '+esc(label('tenants',r.co_tenant_id)):''}</span>`,esc(label('properties',r.property_id)),`${dateText(r.start)}<span class="sub">${r.term==='Fixed'?dateText(r.end):'Month-to-month'}</span>`,cash(r.rent),badge(r.status)]}
else if(kind==='payments'){headers=['Date / receipt','Tenant','Property','For','Method','Received',''];cells=r=>{const receipt=records('receipts').find(x=>x.payment_id===r.id);return [`${link(kind,r.id,dateText(r.date))}<span class="sub">${receipt?`R-${String(receipt.number).padStart(5,'0')}`:r.imported_summary?'Imported summary':''} ${r.void?'· VOID':''}</span>`,esc(label('tenants',r.tenant_id)),esc(label('properties',r.property_id)),esc(r.category),esc(r.method||'—'),cash(r.amount)]}}
else if(kind==='charges'){headers=['Due date','Tenant / property','For','Charged','Balance','Status',''];cells=r=>[link(kind,r.id,dateText(r.date)),`${esc(label('tenants',r.tenant_id))}<span class="sub">${esc(label('properties',r.property_id))}</span>`,esc(r.description||r.category),cash(r.amount),cash(balance(r)),badge(chargeStatus(r))]}
else if(kind==='expenses'){headers=['Expense / payee','Property','Category','Date','Amount','Status',''];cells=r=>[`${link(kind,r.id,r.description)}<span class="sub">${esc(r.payee||label('vendors',r.vendor_id))}</span>`,esc(r.property_id?label('properties',r.property_id):'General'),esc(r.category),dateText(r.date),cash(r.amount),badge(r.void?'Void':r.status)]}
else if(kind==='work'){headers=['Work order','Property','Category','Status','Due','Actual / estimate',''];cells=r=>[`${link(kind,r.id,r.title)}<span class="sub">${esc(r.priority)} priority</span>`,esc(label('properties',r.property_id)),esc(r.category),badge(r.status),dateText(r.due),`${cash(total(workCosts(r)))}<span class="sub">Est. ${cash(r.estimate)}</span>`]}
else if(kind==='fields'){headers=['Label','Use on','Type','Required',''];cells=r=>[link(kind,r.id,r.name),esc(meta[r.entity]?.name),esc(r.field_type),r.required?'Yes':'No']}
else if(kind==='categories'){headers=['Category','Use for',''];cells=r=>[link(kind,r.id,r.name),esc(r.scope)]}
else if(kind==='vendors'){headers=['Vendor','Specialty','Email','Phone',''];cells=r=>[link(kind,r.id,r.name),esc(r.trade||'—'),esc(r.email||'—'),esc(r.phone||'—')]}
else{headers=['Name','Property','Status / type','Date',''];cells=r=>[link(kind,r.id,displayName(r)),esc(label('properties',r.property_id)),badge(r.status||r.inspection_type||'Active'),dateText(r.date||r.start)]}
return table(headers,rows.map(r=>`<tr>${cells(r).map(c=>`<td>${c}</td>`).join('')}<td><div class="cell-actions">${kind==='payments'?paymentActionButton(r):`${kind==='charges'&&!r.void&&balance(r)>0?btn('Record payment','pay',kind,r.id):''}${kind==='files'?btn('Open','preview-file','files',r.id):btn('Open','open',kind,r.id)}`}</div></td></tr>`))}
function paymentActionButton(p){return btn('Payment actions','payment-actions','payments',p.id)}
function paymentActionsDialog(id){const p=find('payments',id),receipt=records('receipts').find(r=>r.payment_id===id),tenant=find('tenants',p?.tenant_id);if(!p)return;const receiptAction=receipt?`<a class="action-button" href="/receipt/${receipt.number}" target="_blank" rel="noopener">Print receipt ↗</a>`:btn('Create receipt','create-receipt','payments',p.id);const previewAction=receipt?btn('Preview emailed receipt','preview-email-receipt','payments',p.id):'';let sendAction;if(!receipt)sendAction='<button type="button" disabled title="Create the locked receipt first">Send receipt <span>Create receipt first</span></button>';else if(p.void)sendAction='<button type="button" disabled title="Voided payment receipts cannot be sent">Send receipt <span>Payment is void</span></button>';else if(!state.email_service?.connected)sendAction='<button type="button" disabled title="Connect Google Workspace in Settings">Send receipt <span>Connect email first</span></button>';else if(!tenant?.email)sendAction='<button type="button" disabled title="Add an email address to the tenant">Send receipt <span>Tenant email needed</span></button>';else sendAction=btn('Send receipt to '+tenant.email,'send-receipt','payments',p.id,'primary');openModal('Payment actions',`<div class="modal-body"><p class="muted">${esc(label('tenants',p.tenant_id))} · ${dateText(p.date)} · ${cash(p.amount)}</p><div class="payment-action-list">${receiptAction}${previewAction}${sendAction}${btn('Open payment','open','payments',p.id)}${p.void?'':btn('Void payment','void','payments',p.id)}</div></div><div class="modal-footer"><button data-action="close">Close</button></div>`)}
function lockedReceiptPreview(snapshot,ref){const owner=snapshot.owner||{},rows=[['Received from',snapshot.tenant_name],['Property',snapshot.property_name],['Address',snapshot.property_address],['For',snapshot.category],['Description',snapshot.description],['Amount received',cash(snapshot.amount)],['Payment method',snapshot.method],['Reference',snapshot.reference]];return `<section class="locked-receipt-preview"><header><h2>Payment receipt</h2><p>${esc(ref)} &nbsp;|&nbsp; ${esc(snapshot.date||'')}</p>${snapshot.void?'<strong class="receipt-void">VOID · Not a valid receipt</strong>':''}</header><div class="locked-receipt-owner"><strong>${esc(owner.business||owner.name||'Property manager')}</strong>${owner.address?`<span>${esc(owner.address)}</span>`:''}${owner.email?`<span>${esc(owner.email)}</span>`:''}</div><dl>${rows.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value||'—')}</dd></div>`).join('')}</dl><footer>This receipt records a payment entered by the property owner.</footer></section>`}
function emailedReceiptPreview(id){const p=find('payments',id),receipt=records('receipts').find(r=>r.payment_id===id),tenant=find('tenants',p?.tenant_id);if(!p||!receipt){toast('Create the locked receipt before previewing the email.');return}const snapshot={...(receipt.snapshot||{}),void:p.void},ref=`R-${String(receipt.number).padStart(5,'0')}`,property=snapshot.property_name||label('properties',p.property_id),to=tenant?.email||'Tenant email not added',subject=`Payment receipt ${ref} — ${property}`;openModal('Email receipt preview',`<div class="modal-body email-preview"><div class="email-preview-card"><dl><div><dt>To</dt><dd>${esc(to)}</dd></div><div><dt>Subject</dt><dd>${esc(subject)}</dd></div></dl><div class="email-preview-message"><p>Hello ${esc(snapshot.tenant_name||tenant?.name||'tenant')},</p><p>Your payment receipt ${esc(ref)} is attached.</p><p>Property: ${esc(property)}<br>Payment date: ${esc(snapshot.date||p.date)}<br>Amount received: ${cash(snapshot.amount??p.amount)}<br>Payment method: ${esc(snapshot.method||p.method||'—')}</p><p class="muted">This email was sent from Hearth on behalf of your property manager.</p></div></div><div class="email-preview-attachment-head"><h3 class="email-preview-heading">PDF attachment · ${esc(ref)}-payment-receipt.pdf</h3><a class="download-link text-link" href="/receipt/${receipt.number}.pdf">Download PDF</a></div>${lockedReceiptPreview(snapshot,ref)}</div><div class="modal-footer"><button type="button" data-action="payment-actions" data-id="${p.id}">Back</button>${!p.void&&tenant?.email&&state.email_service?.connected?btn('Send receipt to '+tenant.email,'send-receipt','payments',p.id,'primary'):''}</div>`);modal.classList.add('file-preview-dialog')}
function sectionTabs(kind){if(['payments','charges'].includes(kind))return `<div class="tabs"><a class="nav-link ${kind==='payments'?'active':''}" href="#payments">Payments received</a><a class="nav-link ${kind==='charges'?'active':''}" href="#charges">Charges & balances</a><button data-action="generate">Generate rent charges</button></div>`;if(['properties','units'].includes(kind))return `<div class="tabs"><a class="nav-link ${kind==='properties'?'active':''}" href="#properties">Properties</a><a class="nav-link ${kind==='units'?'active':''}" href="#units">Units</a></div>`;if(kind==='work')return `<div class="tabs"><button class="${tabMode.work!=='board'?'active':''}" data-action="work-list">List</button><button class="${tabMode.work==='board'?'active':''}" data-action="work-board">Board</button><a class="nav-link" href="#vendors">Vendors</a></div>`;return ''}
function listPage(kind){const m=meta[kind],rows=visibleRows(kind);let actions=`<a class="text-link" href="/api/export/${kind}">${icon('download')} Export CSV</a>`+btn('+ Add '+m.one,'add',kind,'','primary');let content=pageHead(m.name,m.intro,actions)+sectionTabs(kind);if(kind==='expenses')content+=statTiles([['Total recorded',cash(total(rows.filter(r=>!r.void))),'Current filters','wallet',drill('expenses',rows.filter(r=>!r.void))],['Paid',cash(total(rows.filter(r=>!r.void&&r.status==='Paid'))),'Payments recorded','check',drill('expenses',rows.filter(r=>!r.void&&r.status==='Paid'))],['Unpaid',cash(total(rows.filter(r=>!r.void&&r.status==='Unpaid'))),'Still outstanding','clock',drill('expenses',rows.filter(r=>!r.void&&r.status==='Unpaid'))],['Receipt files',String(records('files').filter(f=>rows.some(r=>r.id===f.record_id)).length),'Linked to these expenses','file',drill('files',records('files').filter(f=>rows.some(r=>r.id===f.record_id)))]]);content+=toolbar(kind);if(!rows.length)return content+`<div class="panel">${empty(records(kind).length?'No matching records':'No '+m.name.toLowerCase()+' yet',records(kind).length?'Try changing your search or filters.':'Add your first '+m.one+' to get started.',records(kind).length?'':kind)}</div>`;if(kind==='properties')return content+`<div class="property-grid">${rows.map(propertyCard).join('')}</div>`;if(kind==='work'&&tabMode.work==='board')return content+`<div class="board">${['Open','Scheduled','In progress','Completed'].map(s=>`<div class="board-col"><h3>${s} · ${rows.filter(r=>r.status===s).length}</h3>${rows.filter(r=>r.status===s).map(r=>`<article class="board-card"><h4>${link(kind,r.id,r.title)}</h4><p>${esc(label('properties',r.property_id))}</p><p>${esc(r.category)} · ${cash(total(workCosts(r)))}</p><p>${r.due?'Due '+dateText(r.due):'No due date'}</p>${badge(r.priority)}</article>`).join('')}</div>`).join('')}</div><p class="muted small">On hold and cancelled requests remain available in List view.</p>`;return content+`<section class="panel">${rowsTable(kind,rows)}</section><p class="muted small">${rows.length} ${rows.length===1?'record':'records'}</p>`}
function relationDisplay(key,value){const refs={property_id:'properties',unit_id:'units',tenant_id:'tenants',co_tenant_id:'tenants',lease_id:'leases',charge_id:'charges',work_id:'work',vendor_id:'vendors'};return refs[key]&&value?link(refs[key],value):esc(value??'—')}
function detail(kind,id){const r=find(kind,id);if(!r)return pageHead('Record unavailable','It may have been archived.')+`<a href="#${kind}">Back to ${esc(meta[kind]?.name||'workspace')}</a>`;const m=meta[kind];let actions=btn('Edit','edit',kind,id,'primary');if(kind==='payments')actions=paymentActionButton(r);if(kind==='charges'&&!r.void&&balance(r)>0)actions=btn('Record payment','pay',kind,id,'primary')+actions;if(['charges','expenses'].includes(kind)&&!r.void)actions+=btn('Void','void',kind,id,'danger');if(!['charges','payments','expenses'].includes(kind))actions+=btn('Archive','archive',kind,id);if(kind==='leases')actions=`<a class="text-link" href="#leases/${id}/builder">Review / build lease →</a>`+`<a class="text-link" target="_blank" href="/lease/${id}">Print summary ↗</a>`+btn('Renew','renew',kind,id)+actions;if(kind==='properties')actions=btn(r.photo_id?'Change photo':'Add photo','property-photo',kind,id)+actions;if(kind==='work')actions=btn('Add work expense','work-expense',kind,id)+actions;
let out=`<p class="eyebrow"><a href="#${kind}">← ${esc(m.name)}</a></p>`+pageHead(displayName(r),`${m.one.charAt(0).toUpperCase()+m.one.slice(1)} details`,actions);if(r.void)out+='<div class="notice">This record is void. It remains in history and is excluded from financial totals.</div>';
if(kind==='properties'&&r.photo_id)out+=`<img class="property-hero" src="/api/files/${r.photo_id}" alt="${esc(r.name)}">`;if(kind==='charges')out+=statTiles([['Charge amount',cash(r.amount),'Amount originally owed','file',drill('charges',[r])],['Received',cash(chargePaid(r)),'Payments applied','up',drill('payments',records('payments').filter(p=>p.charge_id===id&&!p.void))],['Remaining balance',cash(r.void?0:balance(r)),'Still outstanding','wallet',{sections:[{kind:'charges',rows:[r]},{kind:'payments',rows:records('payments').filter(p=>p.charge_id===id&&!p.void)}],note:r.void?'This charge is void and contributes no outstanding balance.':`${cash(r.amount)} charged − ${cash(chargePaid(r))} received = ${cash(balance(r))} remaining.`}],['Status',chargeStatus(r),'As of today','clock',drill('charges',[r]) ]]);
if(kind==='work'){const costs=workCosts(r);out+=statTiles([['Actual costs',cash(total(costs)),'Paid and unpaid expenses','wallet',drill('expenses',costs)],['Estimated cost',cash(r.estimate),'Planning amount only','file',drill('work',[r],'This is the planned estimate on the work order. Actual expenses are tracked separately.')],['Paid so far',cash(total(costs.filter(e=>e.status==='Paid'))),'Cash paid','check',drill('expenses',costs.filter(e=>e.status==='Paid'))],['Remaining estimate',cash(Number(r.estimate||0)-total(costs)),'Estimate minus actual costs','chart',{sections:[{kind:'work',rows:[r]},{kind:'expenses',rows:costs}],note:`${cash(r.estimate)} estimated − ${cash(total(costs))} actual costs = ${cash(Number(r.estimate||0)-total(costs))} remaining.`}]])}
if(kind==='tenants'){const charges=records('charges').filter(c=>c.tenant_id===id&&!c.void);out+=statTiles([['Outstanding',cash(charges.reduce((s,c)=>s+balance(c),0)),'Unpaid charges','wallet',drill('charges',charges.filter(c=>balance(c)>0),`${r.name} · All dates, including future charges. The Balance column adds up to this outstanding total; payments already received are deducted.`)],['Rent & income received',cash(total(records('payments').filter(p=>p.tenant_id===id&&!p.void&&p.category!=='Security deposit'))),'All time','up',drill('payments',records('payments').filter(p=>p.tenant_id===id&&!p.void&&p.category!=='Security deposit'),r.name+' · Excludes deposits and voided payments.')],['Deposit received',cash(total(records('payments').filter(p=>p.tenant_id===id&&!p.void&&p.category==='Security deposit'))),'Held separately from income','file',drill('payments',records('payments').filter(p=>p.tenant_id===id&&!p.void&&p.category==='Security deposit'),r.name)],['Active leases',String(records('leases').filter(l=>(l.tenant_id===id||l.co_tenant_id===id)&&l.status==='Active').length),'Current agreements','home',drill('leases',records('leases').filter(l=>(l.tenant_id===id||l.co_tenant_id===id)&&l.status==='Active'),r.name+' · Includes agreements as a co-tenant.')]])}
if(r.source_system)out+=`<div class="note">Imported from ${esc(r.source_system)}.${r.imported_summary?' Settlement summary: installment dates and credit allocations are not supplied by the export; no new receipt was issued.':''}${r.source_shares_unknown?' Individual rent shares are missing; recurring rent stays off until reviewed.':''}</div>`;const detailsBody=`<div class="panel-body detail-grid">${m.fields.filter(f=>r[f[0]]!==undefined&&r[f[0]]!=='').map(([key,title,type])=>`<div class="detail-item ${type==='textarea'?'full':''}"><small>${esc(title)}</small><div>${type==='money'?cash(r[key]):type==='check'?(r[key]?'Yes':'No'):type==='date'?dateText(r[key]):type==='entity'?esc(meta[r[key]]?.name||r[key]):relationDisplay(key,r[key])}</div></div>`).join('')}${records('fields').filter(f=>f.entity===kind).map(f=>`<div class="detail-item"><small>${esc(f.name)}</small><div>${esc(r.custom?.[f.id]??'—')}</div></div>`).join('')}</div>`;out+=kind==='properties'?collapsiblePanel('Details',detailsBody,'','Property information',true):panel('Details',detailsBody);
if(r.source_raw){const rawTable=table(['Field','Original value'],Object.entries(r.source_raw).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(String(v??''))}</td></tr>`));out+=kind==='properties'?collapsiblePanel('Original import values',rawTable,'','Source fields'):panel('Original import values',`<div class="panel-body"><details><summary>Show the original exported fields</summary>${rawTable}</details></div>`)}const relationKey={properties:'property_id',tenants:'tenant_id',leases:'lease_id',work:'work_id',vendors:'vendor_id'}[kind];if(relationKey){const relatedKinds=kind==='properties'?['units','leases','charges','work','expenses','payments','inspections']:kind==='tenants'?['leases','charges','payments']:kind==='leases'?['charges']:['expenses'];for(const rk of relatedKinds){const related=records(rk).filter(item=>item[relationKey]===id||(kind==='tenants'&&rk==='leases'&&item.co_tenant_id===id));const body=related.length?rowsTable(rk,related):empty('No '+meta[rk].name.toLowerCase()+' linked','Records linked here appear automatically.');const add=`<button class="text-link" data-action="related-add" data-kind="${rk}" data-parent="${kind}" data-id="${id}">+ Add ${meta[rk].one}</button>`;out+=kind==='properties'?collapsiblePanel(meta[rk].name,body,add,`${related.length} ${related.length===1?'record':'records'}`):panel(meta[rk].name,body,add)}}
if(kind==='charges'){const paid=records('payments').filter(p=>p.charge_id===id);out+=panel('Payments against this charge',paid.length?rowsTable('payments',paid):empty('No payments yet','Record a payment when you receive money from your tenant.'))}
if(!['fields','categories'].includes(kind)){const fileRows=records('files').filter(f=>f.record_id===id);const fileBody=`<div class="panel-body">${filesFor(id)}<label class="upload-zone">${icon('plus')} Attach receipts, photos, or signed documents<input type="file" multiple data-upload-kind="${kind}" data-upload-id="${id}" aria-label="Attach files to this record"></label></div>`;out+=kind==='properties'?collapsiblePanel('Files & receipts',fileBody,'',`${fileRows.length} ${fileRows.length===1?'file':'files'}`):panel('Files & receipts',fileBody)}out+=`<p class="muted small">Created ${esc(r.created.slice(0,10))} · Last updated ${esc(r.updated.slice(0,10))}</p>`;return out}
function filesFor(id){return records('files').filter(f=>!id||f.record_id===id).map(f=>`<div class="file-tile">${icon('file')}<div class="file-copy"><button class="file-name-button" type="button" data-action="preview-file" data-id="${f.id}">${esc(f.name)}</button><small>${Math.max(1,Math.round(f.size/1024))} KB · ${f.created.slice(0,10)} ${!id&&f.record_id?'· '+esc(label(f.kind,f.record_id)):''}</small></div>${btn('Open','preview-file','files',f.id)}</div>`).join('')}
function documents(){return pageHead('Documents','Receipts, photos, and lease files, saved with your records.')+`<div class="note">Attach files from a property, lease, expense, or work order to keep them linked. You can also store general documents here.</div>`+panel('Your files',`<div class="panel-body"><label class="upload-zone">${icon('plus')} Add documents<input type="file" multiple data-upload-id="" aria-label="Upload general documents"></label>${filesFor('')||empty('No documents yet','Add a receipt, photo, or lease document.')}</div>`)}
function more(){return pageHead('More tools','The rest of your property workspace.')+`<div class="property-grid">${['units','vendors','inspections','applications','listings','tasks'].map(k=>`<section class="panel"><div class="panel-body">${icon(meta[k].icon)}<h2 style="font:24px Georgia">${meta[k].name}</h2><p class="muted small">${meta[k].intro}</p><a class="text-link" href="#${k}">Open ${meta[k].name.toLowerCase()} →</a></div></section>`).join('')}</div><div class="note">Listings and applications are private management records. This local app does not publish advertisements, contact applicants, run screening, or collect money online.</div>`}
function reports(){const f=filters.reports||{};const start=f.start||today().slice(0,4)+'-01-01',end=f.end||today();const valid=(r,dt='date')=>!r.void&&(!f.property||r.property_id===f.property)&&r[dt]>=start&&r[dt]<=end;const ps=records('payments').filter(r=>valid(r));const ex=records('expenses').filter(r=>r.status==='Paid'&&valid(r,'paid_date'));const income=total(ps.filter(p=>p.category!=='Security deposit')),spent=total(ex);const costs=records('expenses').filter(r=>valid(r));const outstanding=records('charges').filter(c=>!c.void&&(!f.property||c.property_id===f.property)&&balance(c)>0);const work=records('work').filter(w=>!f.property||w.property_id===f.property);const leases=records('leases').filter(l=>l.status==='Active'&&(!f.property||l.property_id===f.property));return pageHead('Reports','Understand your income, costs, and the work behind them.',btn('Print / Save PDF','print'))+`<div class="toolbar">${propertyFilter('reports','Report property')}<label>From <input type="date" aria-label="Report start date" data-filter="start" data-kind="reports" value="${start}"></label><label>To <input type="date" aria-label="Report end date" data-filter="end" data-kind="reports" value="${end}"></label></div>${start>end?'<div class="notice">Choose an end date on or after the start date.</div>':''}<p class="print-only">${dateText(start)} – ${dateText(end)} · ${f.property?esc(label('properties',f.property)):'All properties'}</p>`+(ps.some(p=>p.imported_summary)?'<div class="notice">Includes imported settlement summaries. Original installment dates and credit allocations were not provided, so historical cash timing may require reconciliation. See Import / Export history.</div>':'')+statTiles([['Income received',cash(income),'Cash basis · excludes deposits','up',drill('payments',ps.filter(p=>p.category!=='Security deposit'),`${dateText(start)} – ${dateText(end)} · ${f.property?label('properties',f.property):'All properties'}`)],['Expenses paid',cash(spent),'By payment date','down',drill('expenses',ex,`${dateText(start)} – ${dateText(end)} · ${f.property?label('properties',f.property):'All properties'}`)],['Net cash flow',cash(income-spent),'Income less paid expenses','chart',{sections:[{kind:'payments',rows:ps.filter(p=>p.category!=='Security deposit'),title:'Income received'},{kind:'expenses',rows:ex,title:'Paid expenses'}],note:`${dateText(start)} – ${dateText(end)} · ${f.property?label('properties',f.property):'All properties'} · ${cash(income)} income − ${cash(spent)} expenses = ${cash(income-spent)} net cash flow.`}],['Deposits received',cash(total(ps.filter(p=>p.category==='Security deposit'))),'Shown separately from income','wallet',drill('payments',ps.filter(p=>p.category==='Security deposit'),`${dateText(start)} – ${dateText(end)} · ${f.property?label('properties',f.property):'All properties'}`)]])+`<div class="grid-two"><div>${panel('Paid expenses by category',`<div class="panel-body">${bars(categoriesOf(ex))}</div>`)}${panel('Costs by type of work',costs.length?table(['Work category','Paid','Unpaid','Total cost'],categoriesOf(costs.filter(e=>e.work_id)).map(c=>{const rows=costs.filter(e=>e.work_id&&e.category===c.name);return `<tr><td>${esc(c.name)}</td><td>${cash(total(rows.filter(e=>e.status==='Paid')))}</td><td>${cash(total(rows.filter(e=>e.status==='Unpaid')))}</td><td><strong>${cash(c.amount)}</strong></td></tr>`})):empty('No costs recorded','Link expense records to work orders to build this report.'),'','Linked work expenses by invoice date; estimates are excluded.')}</div><div>${panel('Cash flow by property',table(['Property','Income','Paid costs','Net'],[...records('properties').filter(p=>!f.property||p.id===f.property),{id:'',name:'General expenses'}].map(p=>{const inc=total(ps.filter(x=>x.property_id===p.id&&x.category!=='Security deposit'));const exp=total(ex.filter(x=>(x.property_id||'')===p.id));return `<tr><td>${esc(p.name)}</td><td>${cash(inc)}</td><td>${cash(exp)}</td><td>${cash(inc-exp)}</td></tr>`})))}</div></div>`+panel('Rent roll',leases.length?rowsTable('leases',leases):empty('No active leases','Active agreements appear here.'))+panel('Outstanding tenant balances',outstanding.length?rowsTable('charges',outstanding):empty('No outstanding balances','All recorded charges are paid or there are no charges yet.'),'','Current balances across all dates.')+panel('Work costs: actual versus estimate',work.length?table(['Work / property','Category','Status','Estimate','Actual costs','Difference'],work.map(w=>{const actual=total(costs.filter(e=>e.work_id===w.id));return `<tr><td>${link('work',w.id,w.title)}<span class="sub">${esc(label('properties',w.property_id))}</span></td><td>${esc(w.category)}</td><td>${badge(w.status)}</td><td>${cash(w.estimate)}</td><td>${cash(actual)}</td><td>${cash(Number(w.estimate||0)-actual)}</td></tr>`})):empty('No work orders','Track repairs and improvements to compare planned and actual costs.'),'','Actual expenses in the selected date range. Each expense is counted once.')+panel('Expense detail',ex.length?rowsTable('expenses',ex):empty('No paid expenses','Paid expense detail appears here.'),'<a class="text-link" href="/api/export/expenses">Export all expenses CSV ↓</a>')}
function settings(){return pageHead('Settings','Make the workspace fit the way you manage your houses.')+`<div class="grid-two"><div>${panel('Owner & receipt details',`<div class="panel-body"><form id="owner-form"><div class="form-grid">${[['name','Owner name'],['business','Business / receipt heading'],['email','Email'],['address','Mailing address']].map(([key,label])=>`<label class="field">${label}<input name="${key}" value="${esc(state.owner?.[key]||'')}"></label>`).join('')}</div><p class="muted small">Used on new receipts. Previously issued receipts keep their original details.</p><button class="primary" type="submit">Save details</button><p class="form-error" role="alert"></p></form></div>`)}${panel('Custom fields',`<div class="panel-body"><p class="muted small">Create text, number, date, choice, and yes/no fields on any main record.</p>${records('fields').map(f=>`<div class="list-card"><div><h3>${esc(f.name)}</h3><p>${esc(meta[f.entity]?.name)} · ${esc(f.field_type)}${f.required?' · Required':''}</p></div>${btn('Edit','edit','fields',f.id)}</div>`).join('')}</div>`,btn('+ Add field','add','fields','','primary'))}${panel('Work & expense categories',`<div class="panel-body"><p class="muted small">Work categories are also available on expenses, so reports use consistent labels.</p><div class="actions">${records('categories').map(c=>`<button class="badge" data-action="edit" data-kind="categories" data-id="${c.id}">${esc(c.name)} · ${esc(c.scope)}</button>`).join('')}</div></div>`,btn('+ Add category','add','categories'))}</div><div>${panel('Import / Export',`<div class="panel-body stack"><p>Move data between Hearth and other property management apps.</p>${btn('Import data','import')}${btn('Export data','export-data')}<a class="text-link" href="#transfers">Import history & source files →</a></div>`)}${panel('Backups & data',`<div class="panel-body stack"><p class="muted small">Backups include the database and all uploaded receipt and document files. Store a copy outside this computer.</p><a href="/api/backup"><button>${icon('download')} Download full backup</button></a><p class="muted small">Import properties, units, tenants, vendors, or expenses. Export any list as CSV.</p><p class="muted small">To restore a backup, close Hearth and use the Open Hearth launcher in the app folder.</p></div>`)}${panel('Archived records',state.archived.length?state.archived.map(r=>`<div class="list-card"><div><h3>${esc(displayName(r))}</h3><p>${esc(meta[r.kind]?.name)}</p></div>${btn('Restore','restore',r.kind,r.id)}</div>`).join(''):empty('No archived records','Archived nonfinancial records can be restored here.'))}${panel('Recent changes',`<div class="panel-body">${records('audit').slice(0,15).map(a=>`<div class="task-row"><div class="task-copy"><b>${esc(a.action)} · ${esc(meta[a.kind]?.one||a.kind)}</b><span>${esc(a.at.replace('T',' ').slice(0,16))} UTC</span></div></div>`).join('')||'<p class="muted small">Changes are logged as you work.</p>'}</div>`)}</div></div>`}
let disposeLeaseBuilder=null;
function render(){if(disposeLeaseBuilder){if(location.hash===disposeLeaseBuilder.route)return;if(!disposeLeaseBuilder.canLeave()){history.replaceState(null,'',disposeLeaseBuilder.route);return;}}disposeLeaseBuilder?.();disposeLeaseBuilder=null;kpiDetails=[];tableScope='';tableCounts.clear();const [route,id,view]=(location.hash.replace(/^#/,'')||'overview').split('/');let content,title;try{if(route==='leases'&&id&&view==='builder'&&find('leases',id)){app.innerHTML=shell('<div id="lease-builder-root"></div>','Lease document');disposeLeaseBuilder=mountLeaseBuilder(document.querySelector('#lease-builder-root'),{lease:find('leases',id),state,save:async(record,document)=>{await api('save',{kind:'leases',id,version:record.version,data:{...record,document}});state=await api('state');return find('leases',id)},attach:async(file,recordId)=>{await uploadFile(file,recordId);state=await api('state')},filesHTML:()=>filesFor(id)});return;}if(id&&meta[route]){content=detail(route,id);title=meta[route].name}else if(meta[route]){content=listPage(route);title=meta[route].name}else{title=route.charAt(0).toUpperCase()+route.slice(1);content=({overview,documents,reports,settings,more,transfers:transferPage}[route]||overview)()}app.innerHTML=shell(content,title)}catch(e){app.innerHTML=shell(pageHead('Unable to display this page',e.message)+btn('Reload workspace','reload'));console.error(e)}}
function optionsFor(type,source,data){if(type==='entity')return Object.keys(meta).filter(k=>!['fields','categories'].includes(k)).map(k=>[k,meta[k].name]);if(type==='category'){let scopes=source==='work'?['Work']:source==='income'?['Income','Deposit']:['Work','Expense'];return [...new Set(records('categories').filter(c=>scopes.includes(c.scope)).map(c=>c.name))].map(n=>[n,n])}if(type==='ref'){return records(source).filter(r=>!['units','work','leases','charges'].includes(source)||!data.property_id||r.property_id===data.property_id).filter(r=>source!=='charges'||(!r.void&&balance(r)>0&&(!data.tenant_id||r.tenant_id===data.tenant_id))).map(r=>[r.id,source==='charges'?`${dateText(r.date)} · ${r.category} · ${cash(balance(r))} remaining`:displayName(r)])}return (source||[]).map(s=>[s,s])}
function fieldHTML(field,data,custom=false){let [key,title,type='text',required=false,source,def]=field;const value=data[key]??def??(type==='date'&&['date','start'].includes(key)?today():'');const name=custom?'custom_'+key:key;if(type==='check') required=false;const attr=`name="${name}" id="field-${name}" ${required?'required':''}`;let input;if(['ref','select','entity','category'].includes(type)){let opts=optionsFor(type,source,data);if(value&&!opts.some(o=>String(o[0])===String(value)))opts.push([value,value]);input=dropdown({options:opts,value,blank:required?'Select…':'None',attrs:{name,id:'field-'+name,required}})}else if(type==='textarea'){input=`<textarea ${attr} rows="4">${esc(value)}</textarea>`}else if(type==='check'){return `<label class="field check"><input type="checkbox" ${attr} ${value?'checked':''}>${esc(title)}</label>`}else if(type==='multicheck'){const selected=normaliseMultiValues(value),choices=[...(source||[])];selected.filter(item=>!choices.includes(item)).forEach(item=>choices.push(item));return `<fieldset class="field full checklist-field"><legend>${esc(title)}${required?' *':''}</legend><div class="checklist-options">${choices.map((option,index)=>`<label><input type="checkbox" name="${name}" value="${esc(option)}" ${selected.includes(option)?'checked':''}>${esc(option)}</label>`).join('')}</div></fieldset>`}else{input=`<input ${attr} type="${['money','number','integer'].includes(type)?'number':type}" ${['money','number','integer'].includes(type)?`step="${type==='integer'?'1':'0.01'}" min="0"`:''} ${key==='due_day'?'max="31" min="1"':''} value="${esc(value)}">`}return `<label class="field ${type==='textarea'?'full':''}">${esc(title)}${required?' *':''}${input}</label>`}
function formData(form,kind){const fd=new FormData(form),data={};for(const [key,title,type='text'] of meta[kind].fields){data[key]=type==='check'?fd.has(key):type==='multicheck'?fd.getAll(key).join(', '):fd.get(key)??'';if(['money','number','integer'].includes(type)&&data[key]!=='')data[key]=Number(data[key])}data.custom={};for(const f of records('fields').filter(f=>f.entity===kind)){data.custom[f.id]=f.field_type==='Yes / No'?fd.has('custom_'+f.id):fd.get('custom_'+f.id)??''}return data}
function updateLeaseSplit(form){const preview=form.querySelector('#lease-split-preview');if(!preview)return;const total=Number(form.elements.rent.value||0),coId=form.elements.co_tenant_id.value,coShare=Number(form.elements.co_tenant_share.value||0),primaryId=form.elements.tenant_id.value;const primary=label('tenants',primaryId)||'Primary tenant';if(!coId){preview.textContent=`${primary} is responsible for the full ${cash(total)} monthly rent. Choose a co-tenant to split the monthly charges.`;return}const co=label('tenants',coId)||'Co-tenant';preview.textContent=`Monthly split: ${primary} ${cash(Math.max(0,total-coShare))} + ${co} ${cash(coShare)} = ${cash(total)}. Hearth will create and track a separate charge and receipt for each tenant.`}
function openModal(title,body,footer=''){modal.classList.remove('results-dialog','file-preview-dialog');modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer}`;if(!modal.open)modal.showModal()}
function filePreviewDialog(id){const file=find('files',id);if(!file){toast('This file could not be found.');return}const url=`/api/files/${file.id}`,mime=(file.mime||file.type||'').toLowerCase();let preview;if(mime.startsWith('image/'))preview=`<img class="file-preview-image" src="${url}" alt="${esc(file.name)}">`;else if(mime==='application/pdf'||file.name.toLowerCase().endsWith('.pdf'))preview=`<iframe class="file-preview-frame" src="${url}" title="Preview of ${esc(file.name)}"></iframe>`;else preview=`<div class="empty file-preview-unavailable">${icon('file')}<h3>Preview unavailable</h3><p>This file type cannot be shown inside Hearth. You can download it below.</p></div>`;openModal(file.name,`<div class="modal-body file-preview-body">${preview}</div><div class="modal-footer"><button type="button" data-action="close">Close</button><a class="download-link button-link" href="${url}">${icon('download')} Download file</a></div>`);modal.classList.add('file-preview-dialog')}
function openForm(kind,id='',initial={}){const original=id?find(kind,id):null;let data={...initial,...original};const m=meta[kind];if(id&&kind==='payments'){toast('Issued payments are immutable. Void and replace a payment to correct it.');return}const defaults={};m.fields.forEach(([key,t,type,req,source,def])=>{if(type==='select'&&req)defaults[key]=source[0];if(def!==undefined)defaults[key]=def});data={...defaults,...data};const custom=records('fields').filter(f=>f.entity===kind);const hints={leases:'Set the total rent and each tenant’s share. Hearth creates a separate monthly charge for each tenant, so their payments, balances, and receipts stay separate. Mid-month starts are not prorated automatically. Late fees are charged manually.',payments:'Record a payment you have already received. Saving creates a numbered printable receipt; it does not move money.',expenses:'Actual costs belong here. Link to a work order so its cost totals update automatically.',work:'The estimate is for planning. Record actual costs as linked expenses so totals are counted once.',inspections:'Record room-by-room findings, then attach condition photos after saving.',listings:'Private listing record. Publishing to external rental websites is not connected.',fields:'Required fields apply when records are next saved. Choice values are separated by commas.'};
openModal((id?'Edit ':'Add ')+m.one,`<form id="record-form" data-kind="${kind}" data-id="${id}"><div class="modal-body">${hints[kind]?`<div class="note">${hints[kind]}</div>`:''}<div class="form-grid">${m.fields.map(f=>fieldHTML(f,data)).join('')}${kind==='leases'?'<div id="lease-split-preview" class="note full" aria-live="polite"></div>':''}${custom.length?'<div class="form-section">Your custom fields</div>':''}${custom.map(f=>fieldHTML([f.id,f.name,{'Text':'text','Long text':'textarea','Number':'number','Date':'date','Choice':'select','Yes / No':'check'}[f.field_type],f.required,f.field_type==='Choice'?f.options.split(',').map(s=>s.trim()):null],data.custom||{},true)).join('')}${!['fields','categories'].includes(kind)?'<div class="form-section">Attachments</div><label class="field full">Receipt, photo, or document<input type="file" name="attachments" multiple><small>Up to 20 MB per file. You can attach more files later.</small></label>':''}</div><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${id?'Save changes':kind==='payments'?'Save payment & receipt':'Save '+m.one}</button></div></form>`);
const form=document.querySelector('#record-form');if(kind==='leases'){updateLeaseSplit(form);form.addEventListener('input',()=>updateLeaseSplit(form))}form.addEventListener('change',e=>{if(['property_id','tenant_id'].includes(e.target.name)){const current=formData(form,kind);for(const [key,,type,,source] of m.fields){if(type==='ref'&&['units','work','leases','charges'].includes(source)){const select=form.elements[key];const old=select.value;const opts=optionsFor('ref',source,current);updateDropdown(select,opts,{value:old,blank:select.required?'Select…':'None'});}}}if(e.target.name==='charge_id'&&e.target.value){const c=find('charges',e.target.value);for(const [k,v] of Object.entries({property_id:c.property_id,tenant_id:c.tenant_id,category:c.category,amount:balance(c),description:c.description||c.category})){if(form.elements[k])form.elements[k].value=v}}if(e.target.name==='status'&&kind==='expenses'&&e.target.value==='Paid'&&!form.elements.paid_date.value)form.elements.paid_date.value=today();if(kind==='leases')updateLeaseSplit(form)});
form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;const error=form.querySelector('.form-error');error.textContent='';try{const values={...(original||{}),...formData(form,kind)};const saved=await api('save',{kind,id:id||undefined,version:original?.version,data:values});const files=[...(form.elements.attachments?.files||[])];let uploadError='';for(const file of files){try{await uploadFile(file,saved.id)}catch(err){uploadError=err.message;break}}modal.close();await refresh();location.hash=kind+'/'+saved.id;render();toast(uploadError?'Record saved, but an attachment failed: '+uploadError:m.one.charAt(0).toUpperCase()+m.one.slice(1)+' saved.')}catch(err){error.textContent=err.message;submit.disabled=false}})}
async function uploadFile(file,id){if(file.size>20*1024*1024)throw Error(file.name+' exceeds 20 MB.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Unable to read '+file.name));reader.readAsDataURL(file)});return api('upload',{name:file.name,content,record_id:id})}
function confirmAction(title,message,action,label='Confirm',type=''){const resolvedType=type||(/^(Void|Delete|Remove)/i.test(label)?'danger':'primary');openModal(title,`<div class="modal-body"><p style="line-height:1.8">${esc(message)}</p><p class="form-error" role="alert"></p></div><div class="modal-footer"><button data-action="close">Cancel</button><button class="button-${resolvedType}" id="confirm-action">${esc(label)}</button></div>`);document.querySelector('#confirm-action').onclick=async e=>{e.target.disabled=true;try{await action();modal.close();await refresh()}catch(err){modal.querySelector('.form-error').textContent=err.message;e.target.disabled=false}}}
function generateDialog(){openModal('Generate rent charges',`<form id="generate-form"><div class="modal-body"><div class="note">Creates monthly rent charges for active recurring leases from their start date through the date below. Running this again will not duplicate generated charges. Partial first months, late fees, and deposits must be entered separately.</div><label class="field">Generate through<input name="through" type="date" value="${today()}" required></label><p class="muted small">${records('leases').filter(l=>l.status==='Active'&&l.recurring!==false).length} active recurring leases. This records amounts owed; it does not collect money.</p><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary">Generate charges</button></div></form>`);document.querySelector('#generate-form').onsubmit=async e=>{e.preventDefault();const form=e.target;form.querySelector('[type=submit],button.primary').disabled=true;try{const r=await api('generate',{through:form.elements.through.value});modal.close();await refresh();location.hash='charges';toast(`${r.created} rent charges created.`)}catch(err){form.querySelector('.form-error').textContent=err.message;form.querySelector('button.primary').disabled=false}}}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV contains an unclosed quote.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
function importDialog(){openModal('Import CSV',`<form id="import-form"><div class="modal-body"><div class="note">Use a CSV exported from Hearth as your column template. Imports create new records; they do not replace or deduplicate existing records. Linked records use their Hearth IDs. All rows are checked before any are saved.</div><div class="form-grid"><label class="field">Record type${dropdown({attrs:{name:'kind'},options:['properties','units','tenants','vendors','expenses'].map(k=>[k,meta[k].name])})}</label><label class="field">CSV file<input name="csv" type="file" accept=".csv,text/csv" required></label></div><div id="import-preview"></div><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary">Preview import</button></div></form>`);let pending=null;const form=document.querySelector('#import-form');form.onchange=()=>{pending=null;form.querySelector('.primary').textContent='Preview import';document.querySelector('#import-preview').innerHTML=''};form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('.primary');try{if(!pending){const text=await form.elements.csv.files[0].text();const rows=parseCSV(text.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV has no data rows.');const headers=rows.shift().map(h=>h.trim());const kind=form.elements.kind.value;pending={kind,rows:rows.map(cells=>{const obj=Object.fromEntries(headers.map((h,i)=>[h,cells[i]||'']));delete obj.id;delete obj.kind;delete obj.version;delete obj.created;delete obj.updated;delete obj.archived;obj.status=obj.status||({properties:'Active',tenants:'Current',expenses:'Unpaid'}[kind]||'');return obj})};document.querySelector('#import-preview').innerHTML=`<div class="note" style="margin-top:20px">Ready to create ${pending.rows.length} ${esc(meta[kind].name.toLowerCase())}. Columns: ${esc(headers.join(', '))}</div>`;button.textContent='Import '+pending.rows.length+' records';return}button.disabled=true;const result=await api('import',pending);modal.close();await refresh();location.hash=pending.kind;toast(`${result.created} records imported.`)}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.closest('.mobile-toggle'))document.querySelector('.sidebar').classList.toggle('open');return}const {action,kind,id,parent}=b.dataset;try{if(action==='close'){modal.close();return}if(action==='kpi')return kpiDialog(id);if(action==='payment-actions')return paymentActionsDialog(id);if(action==='add')return openForm(kind);if(action==='edit')return openForm(kind,id);if(action==='open'){modal.close();location.hash=kind+'/'+id;return}if(action==='reload')return refresh();if(action==='clear'){filters[kind]={};render();return}if(action==='print'){window.print();return}if(action==='work-list'||action==='work-board'){tabMode.work=action==='work-board'?'board':'list';render();return}if(action==='generate')return generateDialog();if(action==='import')return transferDialog();if(action==='legacy-import')return importDialog();if(action==='property-photo')return propertyPhotoDialog(id);if(action==='export-data')return exportDialog();if(action==='transfers'){location.hash='transfers';return}if(action==='create-receipt'){b.disabled=true;await api('receipts/create',{payment_id:id});modal.close();await refresh();toast('Receipt created and locked to this payment.');return}if(action==='pay'){const c=find('charges',id);return openForm('payments','',{property_id:c.property_id,tenant_id:c.tenant_id,charge_id:c.id,category:c.category,amount:balance(c),description:c.description})}if(action==='work-expense'){const w=find('work',id);return openForm('expenses','',{property_id:w.property_id,work_id:w.id,category:w.category,vendor_id:w.vendor_id,description:w.title})}if(action==='related-add'){const key={properties:'property_id',tenants:'tenant_id',leases:'lease_id',work:'work_id',vendors:'vendor_id'}[parent];const initial={[key]:id};const p=find(parent,id);if(parent==='leases')Object.assign(initial,{property_id:p.property_id,tenant_id:p.tenant_id});if(parent==='work')Object.assign(initial,{property_id:p.property_id,category:p.category,description:p.title});return openForm(kind,'',initial)}if(action==='renew'){const l=find('leases',id);const d={...l,name:l.name+' · renewal',status:'Draft',start:l.end||today(),end:'',term:l.term};delete d.id;delete d.version;delete d.document;return openForm('leases','',d)}if(action==='archive')return confirmAction('Archive '+meta[kind].one,'This hides the record from active lists. You can restore it in Settings. Linked records may prevent archiving.',async()=>{await api('archive',{id});location.hash=kind;toast('Record archived.')},'Archive');if(action==='restore')return confirmAction('Restore record','Return this record to your active workspace.',async()=>{await api('archive',{id,restore:true});toast('Record restored.')},'Restore');if(action==='void'){const r=find(kind,id);return confirmAction('Void '+meta[kind].one,'This excludes the record from totals while keeping its history. A voided payment receipt will be marked VOID. This action cannot be undone in the app.',async()=>{await api('save',{kind,id,version:r.version,data:{...r,void:true}});toast('Record voided.')},'Void record')}}catch(err){b.disabled=false;toast(err.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(action==='email-connect'){const popup=window.open('about:blank','hearth-google-email','width=620,height=760');b.disabled=true;const result=await api('email/google/start',{});if(popup)popup.location=result.url;else window.open(result.url,'_blank');b.disabled=false;return}if(action==='email-replace'){state.email_service={...state.email_service,configured:false,connected:false};render();return}if(action==='email-disconnect')return confirmAction('Disconnect Google Workspace','Hearth will remove its saved Google connection from this computer. You can reconnect later with the OAuth client file.',async()=>{await api('email/google/disconnect',{});toast('Google Workspace disconnected.')},'Remove connection','danger');if(action==='send-receipt'){const tenant=find('tenants',find('payments',id)?.tenant_id);return confirmAction('Send payment receipt',`Send the locked receipt to ${tenant?.email}?`,async()=>{const result=await api('email/send-receipt',{payment_id:id});toast('Receipt sent to '+result.to+'.')},'Send receipt','primary')}}catch(err){b.disabled=false;toast(err.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action="copy-text"]');if(!b)return;try{await copyText(b.dataset.copy||'');const original=b.textContent;b.textContent='Copied';toast('Copied to clipboard.');setTimeout(()=>b.textContent=original,1600)}catch(err){toast(err.message)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="preview-file"]');if(!b)return;filePreviewDialog(b.dataset.id)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="preview-email-receipt"]');if(!b)return;emailedReceiptPreview(b.dataset.id)});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.filter&&el.dataset.filter!=='q'){filters[el.dataset.kind]={...(filters[el.dataset.kind]||{}),[el.dataset.filter]:el.value};render()}if(el.matches('input[type=file][data-upload-id]')){const files=[...el.files];el.disabled=true;let count=0;try{for(const file of files){await uploadFile(file,el.dataset.uploadId);count++}await refresh();toast(`${count} ${count===1?'file':'files'} attached.`)}catch(err){await refresh();toast(`${count} files saved. ${err.message}`)}}});
onSearch('page',(kind,value,element)=>{filters[kind]={...(filters[kind]||{}),q:value};const focused=document.activeElement===element,start=element.selectionStart,end=element.selectionEnd;render();if(focused){const input=document.querySelector('[data-search-scope="page"]');input?.focus({preventScroll:true});input?.setSelectionRange(start,end)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='owner-form')return;e.preventDefault();const form=e.target;const button=form.querySelector('button');button.disabled=true;try{await api('owner',Object.fromEntries(new FormData(form)));await refresh();toast('Receipt details saved.')}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false}});
document.addEventListener('submit',async e=>{if(e.target.id!=='email-setup-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button'),file=form.elements.credentials.files[0],error=form.querySelector('.form-error');button.disabled=true;error.textContent='';try{if(!file||!file.name.toLowerCase().endsWith('.json'))throw Error('Choose the OAuth client JSON downloaded from Google Cloud.');await api('email/google/configure',{email:form.elements.email.value,content:await fileBase64(file)});await refresh();toast('Google connection file saved. Select Connect to sign in.')}catch(err){error.textContent=err.message;button.disabled=false}});
window.addEventListener('message',async e=>{if(e.origin!==location.origin||e.data?.type!=='hearth-google-email')return;await refresh();toast(e.data.connected?'Google Workspace connected.':'Google Workspace did not connect. Review the sign-in window.')});
window.addEventListener('hashchange',()=>{modal.close();render();window.scrollTo(0,0)});
const transferOptions=[['tenantcloud','TenantCloud'],['hearth','Hearth / custom CSV']];
let transferHistory=null, transferHistoryLoading=false;
function transferPage(){
 if(transferHistory===null&&!transferHistoryLoading){transferHistoryLoading=true;api('transfers/history').then(rows=>{transferHistory=rows;if(location.hash==='#transfers')render()}).catch(e=>{transferHistory=[];toast(e.message)}).finally(()=>transferHistoryLoading=false)}
 return pageHead('Import / Export','Bring your records with you. Keep a copy whenever you need it.',btn('Import data','import','','','primary')+btn('Export data','export-data'))+
 `<div class="note">TenantCloud is the first supported app. Choose its account export ZIP, or select individual exported XLSX and CSV files together. Other apps will get their own verified formats as they are added.</div>`+
 panel('Import history',transferHistory===null?'<p class="panel-body">Loading import history…</p>':transferHistory.length?transferHistory.map(b=>`<div class="panel-body transfer-batch"><h3>TenantCloud · ${esc(b.created)}</h3><p>${Object.entries(b.counts).map(([k,v])=>`${v} ${esc(meta[k]?.name||k.replaceAll('_',' '))}`).join(' · ')}</p><p class="muted small">${b.issues.length} rows could not be mapped · ${b.warnings.length} review notes. Original files are retained, including any data that could not be mapped.</p><div class="actions">${b.files.map(f=>`<a class="text-link" href="/api/transfers/original/${f.id}">Download ${esc(f.name)}</a>`).join('')}</div><details><summary>Review import results</summary>${transferSummary(b)}</details></div>`).join(''):empty('No imports yet','Import a full archive or just the sections you need.'))+
 panel('Source history',`<div class="panel-body"><p class="muted small">Credits and unsupported accounting types are preserved here, without treating them as cash income. Original exports remain downloadable above.</p><button id="source-history-button">View preserved transactions</button><div id="source-history"></div></div>`);
}
function transferSummary(s){return `<div class="transfer-summary"><h3>Included in these files</h3><p>${esc(s.included?.join(', ')||'None')}</p>${s.missing?.length?`<div class="notice"><strong>Not included:</strong> ${esc(s.missing.join(', '))}. Only supplied data will appear in Hearth. Missing sections may be empty or intentionally omitted; you can still import.</div>`:''}<h3>Import results</h3>${table(['Section','Count'],Object.entries(s.counts||{}).map(([k,v])=>`<tr><td>${esc(meta[k]?.name||k.replaceAll('_',' '))}</td><td>${v}</td></tr>`))}${s.warnings?.map(w=>`<p class="note">${esc(w)}</p>`).join('')||''}${s.issues?.length?`<details open><summary>${s.issues.length} items need review; other valid records can import</summary>${table(['File / row','Reason'],s.issues.map(i=>`<tr><td>${esc(i.file||'')}${i.row?' · row '+i.row:''}</td><td>${esc(i.reason)}</td></tr>`))}</details>`:''}<details><summary>Files and destinations</summary>${table(['File / sheet','Destination','Rows'],(s.inventory||[]).map(i=>`<tr><td>${esc(i.file)}<span class="sub">${esc(i.sheet||'')}</span></td><td>${esc(meta[i.section]?.name||i.section)}</td><td>${i.rows}</td></tr>`))}</details><details><summary>Record preview</summary>${table(['Source row','Section','Action'],(s.outcomes||[]).slice(0,250).map(r=>`<tr><td>${esc(r.label)}<span class="sub">${esc(r.file)} · row ${r.row}</span></td><td>${esc(meta[r.section]?.name||r.section)}</td><td>${esc(r.action)}</td></tr>`))}</details></div>`}
function transferDialog(){
 openModal('Import data',`<form id="transfer-import"><div class="modal-body"><label class="field">Import from${dropdown({attrs:{name:'source'},options:transferOptions,value:'tenantcloud'})}</label><div id="transfer-instructions" class="note">In TenantCloud: Settings → Account settings → Security → Export data. Choose All time and the sections you want. Download the ZIP from Downloads. You can also choose individual exported XLSX or CSV files; keep the original column headings.</div><label class="field">Export files<input type="file" name="files" multiple accept=".zip,.xlsx,.csv" required><small>Full ZIP or multiple files · 20 MB total. Nothing is saved until you review the preview and select Import.</small></label><div id="transfer-preview"></div><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Preview files</button></div></form>`);
 const form=document.querySelector('#transfer-import');let pending=null;
 form.onchange=e=>{pending=null;form.querySelector('.primary').textContent='Preview files';form.querySelector('#transfer-preview').innerHTML='';form.querySelector('.form-error').textContent='';if(form.elements.source.value==='hearth')importDialog()};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('.primary');button.disabled=true;form.querySelector('.form-error').textContent='';try{
  if(!pending){const selected=[...form.elements.files.files];if(selected.reduce((n,f)=>n+f.size,0)>20*1024*1024)throw Error('Choose files totaling no more than 20 MB.');const files=[];for(const file of selected)files.push({name:file.name,content:await fileBase64(file)});pending=await api('transfers/preview',{source:'tenantcloud',files});form.querySelector('#transfer-preview').innerHTML=transferSummary(pending);button.textContent='Import available data';button.disabled=false;return}
  const result=await api('transfers/commit',{preview_id:pending.preview_id});transferHistory=null;modal.close();await refresh();location.hash='transfers';render();toast(`Import saved. ${result.issues.length} rows could not be mapped. Review the import notes; originals are retained.`)
 }catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false;if(pending&&err.message.includes('Preview')){pending=null;button.textContent='Preview files'}}};
}
document.addEventListener('click',async e=>{const a=e.target.closest('a.download-link,a[href^="/api/export/"],a[href="/api/backup"],a[href^="/api/transfers/original/"]');if(!a)return;e.preventDefault();if(a.dataset.busy)return;a.dataset.busy='1';const text=a.textContent;a.textContent='Preparing file…';try{const response=await fetch(a.getAttribute('href'));if(!response.ok){let message='Unable to download the export.';try{message=(await response.json()).error||message}catch{}throw Error(message)}const blob=await response.blob();const url=URL.createObjectURL(blob);const save=document.createElement('a');save.href=url;const disposition=response.headers.get('Content-Disposition')||'';save.download=disposition.match(/filename="([^"]+)"/)?.[1]||(disposition.includes("filename*=UTF-8''")?decodeURIComponent(disposition.split("filename*=UTF-8''")[1]):'Hearth-export.csv');document.body.appendChild(save);save.click();save.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Export prepared. Check your browser downloads.')}catch(err){toast(err.message)}finally{delete a.dataset.busy;a.textContent=text}});
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Unable to read '+file.name));reader.readAsDataURL(file)})}
function exportDialog(){
 openModal('Export data',`<form id="transfer-export"><div class="modal-body"><label class="field">Export format${dropdown({attrs:{name:'target'},options:transferOptions,value:'hearth'})}</label><label class="field">Section${dropdown({attrs:{name:'section'}})}</label><label class="field" id="export-scope-field" hidden>Lease selection${dropdown({attrs:{name:'scope'},options:[['active','Active leases only'],['all','All leases']]})}</label><p id="export-hint" class="note"></p><div id="export-preview"></div><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" data-action="close">Close</button><button class="primary" type="submit">Prepare download</button></div></form>`);
 const form=document.querySelector('#transfer-export');const sections=()=>{const tc=form.elements.target.value==='tenantcloud';updateDropdown(form.elements.section,(tc?['properties','tenants','leases','transactions']:Object.keys(meta)).map(k=>[k,k==='transactions'?'Transactions — source archive (not an import template)':meta[k].name]));form.querySelector('#export-hint').textContent=tc?'Properties, tenants, and leases use the official TenantCloud import column templates. Each file contains at most 500 records. Transaction exports are for reference; a TenantCloud transaction import has not been verified.':'Download the selected records in Hearth’s own CSV format, including custom fields. Use a full backup to preserve relationships and attachments together.'};sections();form.onchange=e=>{if(e.target.name==='target')sections();document.querySelector('#export-scope-field').hidden=!(form.elements.target.value==='tenantcloud'&&form.elements.section.value==='leases');form.querySelector('#export-preview').innerHTML='';form.querySelector('.form-error').textContent=''};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('.primary');button.disabled=true;try{const section=form.elements.section.value,scope=section==='leases'?form.elements.scope.value:'all';if(form.elements.target.value==='hearth'){form.querySelector('#export-preview').innerHTML=`<a class="download-link" download href="/api/export/${section}">Download Hearth ${esc(meta[section].name)} CSV ↓</a>`}else{const s=await api('transfers/export-preview?section='+section+'&scope='+scope);form.querySelector('#export-preview').innerHTML=`<p>${s.count} records · ${s.parts} ${s.parts===1?'CSV file':'CSV files in a ZIP'}</p>${s.warnings.map(w=>`<p class="note">${esc(w)}</p>`).join('')}${s.errors.length?`<div class="notice"><strong>Complete these fields before export:</strong><ul>${s.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<a class="download-link" download href="/api/transfers/export?section=${section}&scope=${scope}">Download TenantCloud ${esc(section)} ${s.parts>1?'ZIP':'CSV'} ↓</a>`}`} }catch(err){form.querySelector('.form-error').textContent=err.message}finally{button.disabled=false}};
}
function propertyPhotoDialog(id){
 const p=find('properties',id);const images=records('files').filter(f=>f.record_id===id&&['image/jpeg','image/png','image/webp','image/gif'].includes(f.mime));
 openModal('Home photo',`<form id="property-photo-form"><div class="modal-body"><p>Choose the photo shown on ${esc(p.name)} in Your properties.</p>${p.photo_id?`<img class="photo-preview" src="/api/files/${p.photo_id}" alt="Current property photo">`:''}<label class="field">Upload a home photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp,image/gif"><small>JPEG, PNG, WebP, or GIF · up to 20 MB</small></label>${images.length?`<label class="field">Or use an attached image${dropdown({attrs:{name:'existing'},options:images.map(f=>[f.id,f.name]),blank:'Choose an image…'})}</label>`:''}<p class="form-error" role="alert"></p></div><div class="modal-footer">${p.photo_id?'<button type="button" id="remove-home-photo">Use placeholder</button>':''}<button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save photo</button></div></form>`);
 const form=document.querySelector('#property-photo-form');const save=async photo=>{await api('save',{kind:'properties',id:p.id,version:p.version,data:{...p,photo_id:photo}});modal.close();await refresh();toast('Property photo updated.')};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('.primary');button.disabled=true;try{const file=form.elements.photo.files[0];let photo=form.elements.existing?.value;if(file){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw Error('Choose a JPEG, PNG, WebP, or GIF image.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode()}catch{throw Error('The file could not be opened as an image.')}finally{URL.revokeObjectURL(url)}photo=(await uploadFile(file,id)).id}if(!photo)throw Error('Choose a photo first.');await save(photo)}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false}};
 if(p.photo_id)form.querySelector('#remove-home-photo').onclick=async e=>{e.target.disabled=true;try{await save('')}catch(err){form.querySelector('.form-error').textContent=err.message;e.target.disabled=false}};
}
document.addEventListener('click',async e=>{if(e.target.id!=='source-history-button')return;e.target.disabled=true;try{const rows=await api('transfers/source-history');document.querySelector('#source-history').innerHTML=rows.length?table(['Type','Original transaction','Details'],rows.map(r=>`<tr><td>${esc(r.raw.Type||r.category)}</td><td>${esc(r.raw['Transaction ID']||'')}</td><td><details><summary>Original values</summary>${table(['Field','Value'],Object.entries(r.raw).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(String(v))}</td></tr>`))}</details></td></tr>`)): '<p>No preserved transactions.</p>'}catch(err){toast(err.message)}finally{e.target.disabled=false}});

try{await refresh()}catch(e){app.innerHTML=shell(pageHead('Unable to open your workspace','Make sure Hearth is running, then reload this page.')+btn('Try again','reload'));console.error(e)}
// Structured browser tooling is available only when the browser supports WebMCP.
if(navigator.modelContext?.registerTool){navigator.modelContext.registerTool({name:'hearth_workspace_summary',description:'Read property counts and current unpaid balances in the local Hearth workspace.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({properties:records('properties').length,tenants:records('tenants').length,activeLeases:records('leases').filter(l=>l.status==='Active').length,outstanding:records('charges').filter(c=>!c.void).reduce((s,c)=>s+balance(c),0)})}]})})}
